50	// Asserts that fn throws a PatchError with exactly this message and index.
51	export function assertPatchError(fn, message, index) {
52	  let caught;
53	  try {
54	    fn();
55	  } catch (err) {
56	    caught = err;
57	  }
58	  assert.ok(caught !== undefined, `expected PatchError "${message}", nothing was thrown`);
59	  assert.ok(caught instanceof PatchError, `expected PatchError, got ${caught?.name}: ${caught?.message}`);
60	  assert.ok(caught instanceof Error);
61	  assert.equal(caught.name, 'PatchError');
62	  assert.equal(caught.message, message);
63	  assert.equal(caught.index, index);
64	}
