5	const isTypeError = (err) =>
6	  err instanceof TypeError && err.constructor === TypeError && err.message === 'pointer must be a string';
7	const isSyntaxError = (err) =>
8	  err instanceof SyntaxError && err.constructor === SyntaxError && err.message === 'invalid pointer';
