10	describe('parsePointer: structure', () => {
11	  const cases = [
12	    ['', []],
13	    ['/', ['']],
14	    ['/a//b/', ['a', '', 'b', '']],
15	    ['/a', ['a']],
16	    ['/a/b', ['a', 'b']],
17	    ['//', ['', '']],
18	    ['/ ', [' ']],
19	  ];
20	  for (const [pointer, expected] of cases) {
21	    test(`parses ${JSON.stringify(pointer)}`, () => {
22	      assert.deepEqual(parsePointer(pointer), expected);
23	    });
24	  }
25	});
26	
27	describe('parsePointer: escapes', () => {
28	  const cases = [
29	    ['/~01', ['~1']],
30	    ['/~10', ['/0']],
31	    ['/~0', ['~']],
32	    ['/~1', ['/']],
33	    ['/~0~1', ['~/']],
34	    ['/~00', ['~0']],
35	    ['/~11', ['/1']],
36	    ['/a~1b/c~0d', ['a/b', 'c~d']],
37	    ['/~0~0', ['~~']],
38	  ];
39	  for (const [pointer, expected] of cases) {
40	    test(`decodes ${JSON.stringify(pointer)}`, () => {
41	      assert.deepEqual(parsePointer(pointer), expected);
42	    });
43	  }
44	});
45	
46	describe('parsePointer: result', () => {
47	  test('returns a new array on each call', () => {
48	    const a = parsePointer('/a');
49	    const b = parsePointer('/a');
50	    assert.notEqual(a, b);
51	    assert.deepEqual(a, b);
52	  });
53	
54	  test('returns a new array for the empty pointer', () => {
55	    assert.notEqual(parsePointer(''), parsePointer(''));
56	  });
57	
58	  test('result is a real Array', () => {
59	    assert.equal(Array.isArray(parsePointer('/a')), true);
60	    assert.equal(Array.isArray(parsePointer('')), true);
61	  });
62	
63	  test('preserves non-ASCII characters and controls', () => {
64	    assert.deepEqual(parsePointer('/é/日本/\u0000/\n'), ['é', '日本', '\u0000', '\n']);
65	  });
66	
67	  test('does not normalize Unicode', () => {
68	    const decomposed = '/é';
69	    const [token] = parsePointer(decomposed);
70	    assert.equal(token, 'é');
71	    assert.notEqual(token, 'é');
72	    assert.equal(parsePointer('/é')[0], 'é');
73	  });
74	});
