83	    ['0', 0],
84	    ['1', 1],
85	    ['true', true],
86	    ['empty array', []],
87	    ['array of pointer', ['/a']],
88	    ['plain object', {}],
89	    ['symbol', Symbol('x')],
90	    ['function', () => '/a'],
91	    ['object with toString', withToString],
92	  ];
93	  for (const [label, input] of cases) {
94	    test(`throws TypeError for ${label}`, () => {
95	      assert.throws(() => parsePointer(input), isTypeError);
