104	describe('parsePointer: invalid pointers', () => {
105	  const invalid = ['a', ' /a', '#/a', '~0', '/~', '/~2', '/a~', '/~a', '/~/', '/a/~', '/~~0', '/~01~', '\\/a'];
106	  for (const pointer of invalid) {
107	    test(`throws SyntaxError for ${JSON.stringify(pointer)}`, () => {
108	      assert.throws(() => parsePointer(pointer), isSyntaxError);
